async function syncCloud(keepDraft=false){if(saving.current||(!keepDraft&&live.current.dirty))return;try{const {response:r,value:x}=await requestJSON<any>(stateEndpoint(),{cache:'no-store'});if(r.status===403){if(live.current.draft&&live.current.dirty)backupPlan(live.current.draft);setAccessRole('viewer');setReadOnly(true);setSaveError(x.error||'登录或共享权限已失效，草稿保留在此页；请重新登录或联系管理员。');return;}if(!r.ok||!x.data)throw Error(x.error||'无法读取云端记录');if(saving.current||x.revision<live.current.revision)return;cloudBase.current=structuredClone(x.data);x.data.exercises=libraryExercises(x.data.exercises);setData(x.data);setRevision(x.revision);setAccessRole(x.role||'owner');if(x.role==='viewer')setReadOnly(true);const state=live.current;if(!state.dirty){const same=x.data.sessions.filter((s:Session)=>s.athlete===state.athlete&&s.date===state.date);const chosen=state.sessionChoice?.athlete===state.athlete&&state.sessionChoice.date===state.date?state.sessionChoice.id:state.draft?.id;const saved=same.find((s:Session)=>s.id===chosen)||(!state.sessionChoice?same[0]:null);if(saved){draftBase.current=structuredClone(saved);setDraft(structuredClone(saved));}}if(keepDraft)setMessage('已同步云端；你的草稿仍保留。同一计划有冲突时请另存草稿，或查看云端历史。');}catch(e:any){if(keepDraft)setMessage(e.message);}}
